package com.vityarthi.library.repository;
import com.vityarthi.library.db.Database; import com.vityarthi.library.model.Loan; import java.math.*; import java.sql.*; import java.time.*; import java.util.*;
public class LoanRepository {
 public long insert(Loan l){String q="INSERT INTO loans(book_id,member_id,issue_date,due_date,return_date,fine) VALUES(?,?,?,?,?,?)";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setLong(1,l.getBookId());p.setLong(2,l.getMemberId());p.setString(3,l.getIssueDate().toString());p.setString(4,l.getDueDate().toString());p.setNull(5,Types.VARCHAR);p.setBigDecimal(6,l.getFine());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){return k.next()?k.getLong(1):0;}}catch(SQLException e){throw new IllegalStateException(e);}}
 public Optional<Loan> active(long member,long book){String q="SELECT * FROM loans WHERE member_id=? AND book_id=? AND return_date IS NULL";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,member);p.setLong(2,book);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<Loan> all(){return query("SELECT * FROM loans ORDER BY id");}
 public void close(long id,LocalDate date,BigDecimal fine){try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE loans SET return_date=?,fine=? WHERE id=? AND return_date IS NULL")){p.setString(1,date.toString());p.setBigDecimal(2,fine);p.setLong(3,id);if(p.executeUpdate()==0)throw new IllegalArgumentException("Loan is already closed or missing.");}catch(SQLException e){throw new IllegalStateException(e);}}
 private List<Loan> query(String q){List<Loan>x=new ArrayList<>();try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));return x;}catch(SQLException e){throw new IllegalStateException(e);}}
 private Loan map(ResultSet r)throws SQLException{String d=r.getString("return_date");return new Loan(r.getLong("id"),r.getLong("book_id"),r.getLong("member_id"),LocalDate.parse(r.getString("issue_date")),LocalDate.parse(r.getString("due_date")),d==null?null:LocalDate.parse(d),r.getBigDecimal("fine"));}
}